// Fixed-plan independent inspection and owned cleanup. It never resumes an application.
using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.ComponentModel;using System.Runtime.InteropServices;using System.Security.Principal;using System.Security.AccessControl;using System.Security.Cryptography;using System.Web.Script.Serialization;using Microsoft.Win32;
internal static class LpacProductionRecovery {
    const string Storage="Software\\Classes\\Local Settings\\Software\\Microsoft\\Windows\\CurrentVersion\\AppContainer\\Storage\\";
    static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=16*1024*1024};
    static void Require(bool value,string code){if(!value)throw new InvalidOperationException("PRODUCT_RECOVERY_"+code);}
    static string Hash(string file){LpacInputIdentity.ValidateFile(file);using(var sha=SHA256.Create())using(var stream=File.OpenRead(file))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
    static Dictionary<string,object> Load(string file){Require(new FileInfo(file).Length<=16*1024*1024,"FILE_BUDGET");LpacInputIdentity.ValidateFile(file);return Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));}
    static Dictionary<string,object> Data(Dictionary<string,object> value){return (Dictionary<string,object>)value["data"];}
    static void Save(string file,object value){Directory.CreateDirectory(Path.GetDirectoryName(file));LpacInputIdentity.ValidateDirectory(Path.GetDirectoryName(file));using(var stream=new FileStream(file,FileMode.CreateNew,FileAccess.Write))using(var writer=new StreamWriter(stream,new UTF8Encoding(false)))writer.Write(Json.Serialize(value)+"\n");}
    static bool KeyAbsent(string moniker){using(var key=Registry.CurrentUser.OpenSubKey(Storage+moniker,false))return key==null;}
    static string StorageIdentity(string moniker){using(var key=Registry.CurrentUser.OpenSubKey(Storage+moniker,false)){if(key==null)return null;var acl=key.GetAccessControl(AccessControlSections.Access|AccessControlSections.Owner);Require(acl.GetOwner(typeof(SecurityIdentifier)).Value==WindowsIdentity.GetCurrent().User.Value,"STORAGE_OWNER");return acl.GetSecurityDescriptorSddlForm(AccessControlSections.Access|AccessControlSections.Owner);}}
    static string Sid(string moniker){IntPtr sid;int hr=DeriveAppContainerSidFromAppContainerName(moniker,out sid);if(hr!=0)throw new System.Runtime.InteropServices.COMException("Derive recorded profile SID",hr);try{return new SecurityIdentifier(sid).Value;}finally{FreeSid(sid);}}
    static object[] Ended(IEnumerable<Dictionary<string,object>> events){var observations=new List<object>();foreach(var item in events){string name=(string)item["name"];if(name!="broker_identity"&&name!="process_created_suspended"&&name!="control_created_suspended")continue;var data=Data(item);uint pid=Convert.ToUInt32(data["pid"]);long expected=Convert.ToInt64(data["created_filetime"]);IntPtr handle=OpenProcess(0x101000,false,pid);if(handle==IntPtr.Zero){int error=Marshal.GetLastWin32Error();Require(error==87,"PROCESS_QUERY_UNKNOWN:"+pid+":"+error);observations.Add(new{pid=pid,expected_created_filetime=expected.ToString(),absent=true});continue;}try{long created,ended,kernel,user;if(!GetProcessTimes(handle,out created,out ended,out kernel,out user))throw new Win32Exception(Marshal.GetLastWin32Error(),"Recovery process times");uint wait=WaitForSingleObject(handle,0);Require(wait==0||wait==258,"PROCESS_WAIT_UNKNOWN");bool same=created==expected;Require(!same||wait==0,"PROCESS_STILL_ACTIVE:"+pid);observations.Add(new{pid=pid,expected_created_filetime=expected.ToString(),current_created_filetime=created.ToString(),same_identity=same,ended=wait==0});}finally{CloseHandle(handle);}}return observations.ToArray();}
    static bool JobAbsent(LpacProductionPlan plan){IntPtr job=OpenJobObjectW(4,false,plan.JobName);if(job==IntPtr.Zero){int error=Marshal.GetLastWin32Error();Require(error==2,"JOB_QUERY_UNKNOWN:"+error);return true;}try{var data=new Accounting();uint returned;if(!QueryInformationJobObject(job,1,ref data,(uint)Marshal.SizeOf(typeof(Accounting)),out returned))throw new Win32Exception(Marshal.GetLastWin32Error(),"Recovery Job accounting");Require(data.ActiveProcesses==0,"JOB_MEMBERS_STILL_ACTIVE");return false;}finally{CloseHandle(job);}}
    internal static int Run(LpacProductionPlan plan,bool recover){
        Require(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator),"UNELEVATED_OWNER_REQUIRED");
        using(var parent=new LpacParentLifetime(delegate(string name,object value){},plan.DaemonPath,plan.DaemonHash)){
            parent.RequireAlive();string moniker="specforge.regread."+plan.AttemptId,profile=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Packages",moniker),eventFile=Path.Combine(plan.AttemptRoot,"events.jsonl"),sid=Sid(moniker),user=WindowsIdentity.GetCurrent().User.Value;
            bool rootExists=Directory.Exists(plan.AttemptRoot);var events=new Dictionary<string,object>[0];string eventsHash=null;
            if(rootExists){LpacInputIdentity.ValidateDirectory(plan.AttemptRoot);Require(File.Exists(eventFile),"EVENTS_REQUIRED");eventsHash=Hash(eventFile);Require(new FileInfo(eventFile).Length<=16*1024*1024,"EVENT_BUDGET");events=File.ReadAllLines(eventFile).Where(line=>line.Length!=0).Select(line=>Json.Deserialize<Dictionary<string,object>>(line)).ToArray();foreach(var entry in events)Require(entry.Count==3&&entry.ContainsKey("name")&&entry.ContainsKey("utc")&&entry.ContainsKey("data"),"EVENT_SCHEMA");}
            bool jobAbsent=JobAbsent(plan);object[] processes=Ended(events);bool profilePresent=Directory.Exists(profile),storagePresent=!KeyAbsent(moniker);
            long? profileCreated=null;string storageSddl=null;
            if(profilePresent||storagePresent){var absence=events.Where(e=>(string)e["name"]=="product_resource_absence").ToArray();Require(absence.Length==1,"INITIAL_ABSENCE_WITNESS");var witness=Data(absence[0]);Require((string)witness["plan_id"]==plan.PlanId&&(string)witness["attempt_id"]==plan.AttemptId&&(string)witness["config_sha256"]==plan.ConfigHash&&(bool)witness["profile_absent"]&&(bool)witness["storage_absent"]&&(string)witness["job_name"]==plan.JobName,"RESERVATION_IDENTITY");
                long reserved=DateTime.Parse((string)absence[0]["utc"],null,System.Globalization.DateTimeStyles.RoundtripKind).ToUniversalTime().ToFileTimeUtc();
                foreach(var entry in events.Where(e=>(string)e["name"]=="profile_created"))Require((string)Data(entry)["sid"]==sid&&(string)Data(entry)["moniker"]==moniker,"ACTUAL_PROFILE_SID");
                if(profilePresent){LpacInputIdentity.ValidateDirectory(profile);Require(Directory.GetAccessControl(profile).GetOwner(typeof(SecurityIdentifier)).Value==user,"PROFILE_OWNER");profileCreated=Directory.GetCreationTimeUtc(profile).ToFileTimeUtc();Require(profileCreated>=reserved&&profileCreated<=DateTime.UtcNow.ToFileTimeUtc(),"PROFILE_CREATION_TIME");}
                if(storagePresent)storageSddl=StorageIdentity(moniker);
            }
            string folder=Path.Combine(plan.OwnerRoot,"recovery"),intent=Path.Combine(folder,plan.AttemptId+".intent.json"),completed=Path.Combine(folder,plan.AttemptId+".completed.json");
            if(recover&&!File.Exists(completed)){
                if(File.Exists(intent)){var old=Load(intent);Require((string)old["config_sha256"]==plan.ConfigHash&&(string)old["plan_id"]==plan.PlanId&&(string)old["attempt_id"]==plan.AttemptId&&(string)old["user_sid"]==user&&Equals(old["events_sha256"],eventsHash),"INTENT_DRIFT");if(profilePresent)Require(Convert.ToInt64(old["profile_created_filetime"])==profileCreated,"PROFILE_IDENTITY_DRIFT");if(storagePresent)Require((string)old["storage_sddl"]==storageSddl,"STORAGE_ACL_DRIFT");}
                else Save(intent,new{contract="verification-recovery-intent/v1",utc=DateTime.UtcNow.ToString("o"),plan_id=plan.PlanId,attempt_id=plan.AttemptId,config_sha256=plan.ConfigHash,user_sid=user,events_sha256=eventsHash,profile_created_filetime=profileCreated==null?null:profileCreated.ToString(),storage_sddl=storageSddl,application_passed=false});
                Ended(events);JobAbsent(plan);parent.RequireAlive();if(profilePresent||storagePresent){int hr=DeleteAppContainerProfile(moniker);Require(hr==0,"DELETE_PROFILE:"+hr);}Require(!Directory.Exists(profile)&&KeyAbsent(moniker),"RESOURCES_REMAIN");
                Save(completed,new{contract="verification-recovery-completed/v1",utc=DateTime.UtcNow.ToString("o"),plan_id=plan.PlanId,attempt_id=plan.AttemptId,config_sha256=plan.ConfigHash,intent_sha256=Hash(intent),events_sha256=eventsHash,application_passed=false});
            }
            if(File.Exists(completed)){var old=Load(completed);Require((string)old["config_sha256"]==plan.ConfigHash&&(string)old["plan_id"]==plan.PlanId&&(string)old["attempt_id"]==plan.AttemptId&&Equals(old["events_sha256"],eventsHash)&&(string)old["intent_sha256"]==Hash(intent),"COMPLETION_DRIFT");}
            bool clean=!Directory.Exists(profile)&&KeyAbsent(moniker);Require(Hash(plan.ConfigPath)==plan.ConfigHash,"CONFIG_DRIFT");JobAbsent(plan);Ended(events);
            Console.WriteLine(Json.Serialize(new{contract="verification-native-inspection/v1",utc=DateTime.UtcNow.ToString("o"),plan_id=plan.PlanId,attempt_id=plan.AttemptId,config_sha256=plan.ConfigHash,events_sha256=eventsHash,root_created=rootExists,profile_present=Directory.Exists(profile),storage_present=!KeyAbsent(moniker),job_absent=jobAbsent,processes=processes,processes_ended=true,cleanup_proved=clean,recovery_requested=recover,application_passed=false}));return clean?0:1;
        }
    }
    [StructLayout(LayoutKind.Sequential)]struct Accounting{public long UserTime,KernelTime,PeriodUser,PeriodKernel;public uint Faults,TotalProcesses,ActiveProcesses,TerminatedProcesses;}
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr OpenJobObjectW(uint access,[MarshalAs(UnmanagedType.Bool)]bool inherit,string name);
    [DllImport("kernel32.dll",SetLastError=true)][return:MarshalAs(UnmanagedType.Bool)]static extern bool QueryInformationJobObject(IntPtr job,int kind,ref Accounting data,uint size,out uint returned);
    [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr OpenProcess(uint access,[MarshalAs(UnmanagedType.Bool)]bool inherit,uint pid);
    [DllImport("kernel32.dll",SetLastError=true)][return:MarshalAs(UnmanagedType.Bool)]static extern bool GetProcessTimes(IntPtr process,out long created,out long ended,out long kernel,out long user);
    [DllImport("kernel32.dll",SetLastError=true)]static extern uint WaitForSingleObject(IntPtr process,uint ms);
    [DllImport("kernel32.dll")][return:MarshalAs(UnmanagedType.Bool)]static extern bool CloseHandle(IntPtr handle);
    [DllImport("userenv.dll",CharSet=CharSet.Unicode)]static extern int DeriveAppContainerSidFromAppContainerName(string name,out IntPtr sid);
    [DllImport("userenv.dll",CharSet=CharSet.Unicode)]static extern int DeleteAppContainerProfile(string name);
    [DllImport("advapi32.dll")]static extern IntPtr FreeSid(IntPtr sid);
}
